// Modified by Nauchu AB: native TSX, generated fictional portraits and original Mont copy;
// preserves the source's sequential per-character timing. See README for attribution.
// Reference: https://hyperframes.heygen.com/catalog/blocks/yt-comment-card.md
export default defineSpanScene({
  id: "comment-cards", width: 960, height: 540, durationMs: 8000, editPreviewMs: 6000,
  variables: {
    width: numberVar(960), height: numberVar(540), background: colorVar("#0B0F14"),
    foreground: colorVar("#f1f1f1"), muted: colorVar("#aaaaaa"), reply: stringVar("Reply"),
    author1: stringVar("@niabuilds"), age1: stringVar("2 hours ago"), likes1: stringVar("214"),
    avatarImage1: stringVar("data:image/png;base64,"),
    line11: stringVar("One prompt. Three scenes. A real MP4."), line12: stringVar("This is how I want to make videos."),
    author2: stringVar("@eliasframes"), age2: stringVar("38 minutes ago"), likes2: stringVar("86"),
    avatarImage2: stringVar("data:image/png;base64,"),
    line21: stringVar("The reading hold makes every caption land."), line22: stringVar("Small detail. Huge difference."),
    charDelayMs: numberVar(24),
  },
  computeds: {
    scale: computed.number(() => Math.min(vars.width / 960, vars.height / 540)),
    count1: computed.number(() => text.glyphs(vars.line11, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + text.glyphs(vars.line12, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + 1),
    count2: computed.number(() => text.glyphs(vars.line21, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + text.glyphs(vars.line22, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + 1),
    delay1: computed.number(() => Math.min(vars.charDelayMs, 2200 / computed.count1)),
    delay2: computed.number(() => Math.min(vars.charDelayMs, 2200 / computed.count2)),
    start1: computed.number(() => 300),
    start2: computed.number(() => 1350 + computed.count1 * computed.delay1),
    p1: computed.number(() => Math.max(0, Math.min(1, (time.ms - computed.start1) / 450))),
    p2: computed.number(() => Math.max(0, Math.min(1, (time.ms - computed.start2) / 450))),
    pop1: computed.number(() => 1 + 2.6 * Math.pow(computed.p1 - 1, 3) + 1.6 * Math.pow(computed.p1 - 1, 2)),
    pop2: computed.number(() => 1 + 2.6 * Math.pow(computed.p2 - 1, 3) + 1.6 * Math.pow(computed.p2 - 1, 2)),
    meta1: computed.number(() => 1 - Math.pow(1 - Math.max(0, Math.min(1, (time.ms - computed.start1 - 120) / 400)), 3)),
    meta2: computed.number(() => 1 - Math.pow(1 - Math.max(0, Math.min(1, (time.ms - computed.start2 - 120) / 400)), 3)),
    clock: computed.number(() => time.ms),
    actions1: computed.number(() => 1 - Math.pow(1 - Math.max(0, Math.min(1, (time.ms - computed.start1 - 550 - computed.count1 * computed.delay1) / 350)), 3)),
    actions2: computed.number(() => 1 - Math.pow(1 - Math.max(0, Math.min(1, (time.ms - computed.start2 - 550 - computed.count2 * computed.delay2) / 350)), 3)),
    exit: computed.number(() => Math.pow(Math.max(0, Math.min(1, (time.ms - 7470) / 480)), 3)),
  },
  render({ vars, computed }) {
    return <Scene width={vars.width} height={vars.height}>
      <Rect id="background" width={vars.width} height={vars.height} fill={vars.background} />
      {/* Prewarm the generated profiles and the platform action glyph used after typing. */}
      <Repeat items={[vars.avatarImage1, vars.avatarImage2, "data:image/png;base64,"]} render={(uri, i) => <Image borderWidth={0} borderColor="transparent" id={"asset-prewarm-" + i} src={uri} x={-10000} width={1} height={1} />} />
      <Group id="stage" x={(vars.width - 960 * computed.scale) / 2} y={(vars.height - 540 * computed.scale) / 2} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.scale} scaleY={computed.scale}>
        <Group id="comments" x={70} y={176.11 - 9 * computed.exit} opacity={1 - computed.exit} width={0} height={0} pivotX={0} pivotY={0}>
          <Group id="comment-1" y={0} width={0} height={0} pivotX={0} pivotY={0}>
            <Group id="avatar-1" x={16} y={16} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.pop1} scaleY={computed.pop1} opacity={computed.p1}>
              <Image borderWidth={0} borderColor="transparent" id="avatar-portrait-1" x={-16} y={-16} width={32} height={32} src={vars.avatarImage1} />
            </Group>
            <Group id="metadata-1" y={5 * (1 - computed.meta1)} opacity={computed.meta1} width={0} height={0} pivotX={0} pivotY={0}>
<Text id="author-1" text={vars.author1} x={43} y={0} width={200} height={19.575} fontFamily="Inter" fontWeight={700} size={13.5} lineHeight={19.575} color={vars.foreground} fit="none" />
<Text id="age-1" text={vars.age1} x={49 + text.glyphs(vars.author1, { fontFamily: "Inter", fontWeight: 700, fontSize: 13.5 })[0].totalAdvance} y={1.5} width={170} height={16.675} fontFamily="Inter" fontWeight={400} size={11.5} lineHeight={16.675} color={vars.muted} fit="none" />
            </Group>
            <Repeat items={text.glyphs(vars.line11, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })} render={(glyph) => (
              <Text id={"text-1-1-" + glyph.index} text={glyph.text} x={43 + glyph.offset} y={19.5}
                width={Math.max(glyph.advance, glyph.inkWidth + Math.abs(glyph.bearingX)) + 3} height={25}
                fontFamily={glyph.fontFamily} fontWeight={500} size={17} lineHeight={22.95} fit="none" color={vars.foreground}
                opacity={Math.max(0, Math.min(1, (computed.clock - computed.start1 - 400 - (glyph.index + 0) * computed.delay1) / 20))} />
            )} />
            <Repeat items={text.glyphs(vars.line12, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })} render={(glyph) => (
              <Text id={"text-1-2-" + glyph.index} text={glyph.text} x={43 + glyph.offset} y={42.45}
                width={Math.max(glyph.advance, glyph.inkWidth + Math.abs(glyph.bearingX)) + 3} height={25}
                fontFamily={glyph.fontFamily} fontWeight={500} size={17} lineHeight={22.95} fit="none" color={vars.foreground}
                opacity={Math.max(0, Math.min(1, (computed.clock - computed.start1 - 400 - (glyph.index + text.glyphs(vars.line11, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + 1) * computed.delay1) / 20))} />
            )} />
            <Group id="actions-1" x={43} y={71.4} opacity={computed.actions1} width={0} height={0} pivotX={0} pivotY={0}>
<Image borderWidth={0} borderColor="transparent" id="thumb-1" x={0} y={0} width={12} height={12} src={"data:image/png;base64,"} />
<Text id="likes-1" text={vars.likes1} x={17} y={-1} width={25} height={15.95} fontFamily="Inter" fontWeight={600} size={11} lineHeight={15.95} color={vars.muted} fit="none"  />
<Image borderWidth={0} borderColor="transparent" id="thumb-down-1" x={48} y={0} width={12} height={12} src={"data:image/png;base64,"} rotation={180} />
<Text id="reply-1" text={vars.reply} x={78} y={-1} width={65} height={17} fontFamily="Inter" fontWeight={600} size={12} lineHeight={17} color={vars.foreground} fit="none" />
            </Group>
          </Group>
          <Group id="comment-2" y={103.89} width={0} height={0} pivotX={0} pivotY={0}>
            <Group id="avatar-2" x={16} y={16} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.pop2} scaleY={computed.pop2} opacity={computed.p2}>
              <Image borderWidth={0} borderColor="transparent" id="avatar-portrait-2" x={-16} y={-16} width={32} height={32} src={vars.avatarImage2} />
            </Group>
            <Group id="metadata-2" y={5 * (1 - computed.meta2)} opacity={computed.meta2} width={0} height={0} pivotX={0} pivotY={0}>
<Text id="author-2" text={vars.author2} x={43} y={0} width={200} height={19.575} fontFamily="Inter" fontWeight={700} size={13.5} lineHeight={19.575} color={vars.foreground} fit="none" />
<Text id="age-2" text={vars.age2} x={49 + text.glyphs(vars.author2, { fontFamily: "Inter", fontWeight: 700, fontSize: 13.5 })[0].totalAdvance} y={1.5} width={170} height={16.675} fontFamily="Inter" fontWeight={400} size={11.5} lineHeight={16.675} color={vars.muted} fit="none" />
            </Group>
            <Repeat items={text.glyphs(vars.line21, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })} render={(glyph) => (
              <Text id={"text-2-1-" + glyph.index} text={glyph.text} x={43 + glyph.offset} y={19.5}
                width={Math.max(glyph.advance, glyph.inkWidth + Math.abs(glyph.bearingX)) + 3} height={25}
                fontFamily={glyph.fontFamily} fontWeight={500} size={17} lineHeight={22.95} fit="none" color={vars.foreground}
                opacity={Math.max(0, Math.min(1, (computed.clock - computed.start2 - 400 - (glyph.index + 0) * computed.delay2) / 20))} />
            )} />
            <Repeat items={text.glyphs(vars.line22, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })} render={(glyph) => (
              <Text id={"text-2-2-" + glyph.index} text={glyph.text} x={43 + glyph.offset} y={42.45}
                width={Math.max(glyph.advance, glyph.inkWidth + Math.abs(glyph.bearingX)) + 3} height={25}
                fontFamily={glyph.fontFamily} fontWeight={500} size={17} lineHeight={22.95} fit="none" color={vars.foreground}
                opacity={Math.max(0, Math.min(1, (computed.clock - computed.start2 - 400 - (glyph.index + text.glyphs(vars.line21, { fontFamily: "Inter", fontWeight: 500, fontSize: 17 })[0].count + 1) * computed.delay2) / 20))} />
            )} />
            <Group id="actions-2" x={43} y={71.4} opacity={computed.actions2} width={0} height={0} pivotX={0} pivotY={0}>
<Image borderWidth={0} borderColor="transparent" id="thumb-2" x={0} y={0} width={12} height={12} src={"data:image/png;base64,"} />
<Text id="likes-2" text={vars.likes2} x={17} y={-1} width={25} height={15.95} fontFamily="Inter" fontWeight={600} size={11} lineHeight={15.95} color={vars.muted} fit="none"  />
<Image borderWidth={0} borderColor="transparent" id="thumb-down-2" x={48} y={0} width={12} height={12} src={"data:image/png;base64,"} rotation={180} />
<Text id="reply-2" text={vars.reply} x={78} y={-1} width={65} height={17} fontFamily="Inter" fontWeight={600} size={12} lineHeight={17} color={vars.foreground} fit="none" />
            </Group>
          </Group>
        </Group>
      </Group>
    </Scene>;
  },
});
